/**
 * Locators for Reports (/reports, /reports/new, /reports/:id) — AI report assistant and the
 * report preview's Export menu. MCP-verified live (2026-10-21): the chat textbox is labelled
 * "Ask your question", a finished report shows "Generated by ..." text, and the Export menu
 * lists "Export PDF" + "Export data (Excel)" for PDF reports and only "Export Excel" for
 * Excel-source reports.
 */
function reportsLocators(page) {
  return {
    chatInput: page
      .getByRole("textbox", { name: "Ask your question" })
      .or(page.getByPlaceholder("Ask your question"))
      .or(page.locator("main textarea").first()),
    generatedMarker: page
      .locator("main")
      .getByText("Generated by", { exact: false })
      .first(),
    exportButton: page
      .getByRole("button", { name: "Export", exact: true })
      .or(page.locator("main button").filter({ hasText: "Export" }).last()),
    exportPdfItem: page
      .getByRole("menuitem", { name: "Export PDF" })
      .or(page.getByText("Export PDF", { exact: true }))
      .first(),
    exportDataExcelItem: page
      .getByRole("menuitem", { name: "Export data (Excel)" })
      .or(page.getByText("Export data (Excel)", { exact: true }))
      .first(),
    exportExcelItem: page
      .getByRole("menuitem", { name: "Export Excel", exact: true })
      .or(page.getByText("Export Excel", { exact: true }))
      .first(),
    menuItems: page.getByRole("menuitem"),
  };
}

module.exports = { reportsLocators };
